// @FIGURE_CODE_BEGIN
var W = 900, H = 675;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var blue = '#2aa4dc';
var red = '#ef5454';
var black = '#222';
var gray = '#bfc1c4';
var pale = '#fff1d3';

var sampleAlpha = 0.50;
var nSegments = 8;
var currentStep = 0;
var curvePts = [];
var cumLen = [];
var totalLen = 0;
var integralValue = 0;

var zoomArrowLayer = draw.group();
var curveLayer = draw.group();
var dynamicLayer = draw.group();
var labelLayer = draw.group();
var insetLayer = draw.group();
var formulaLayer = draw.group();

var arrowMarker = draw.marker(10, 10, function (add) {
  add.path('M0,0 L10,5 L0,10 z').fill(black);
});
arrowMarker.ref(9, 5).orient('auto');

var smallArrowMarker = draw.marker(8, 8, function (add) {
