});
arrowStartMarker.ref(1, 5).orient('auto');

function cubicPoint(p0, p1, p2, p3, t) {
  var u = 1 - t;
  return {
    x: u * u * u * p0.x + 3 * u * u * t * p1.x + 3 * u * t * t * p2.x + t * t * t * p3.x,
    y: u * u * u * p0.y + 3 * u * u * t * p1.y + 3 * u * t * t * p2.y + t * t * t * p3.y
  };
}

function addCubicSamples(p0, p1, p2, p3, count) {
  for (var i = 0; i <= count; i++) {
    if (curvePts.length && i === 0) continue;
    curvePts.push(cubicPoint(p0, p1, p2, p3, i / count));
  }
}

function buildCurve() {
  curvePts = [];
  addCubicSamples(
    { x: 30, y: 570 }, { x: 125, y: 525 }, { x: 215, y: 430 }, { x: 265, y: 275 }, 90
  );
  addCubicSamples(
    { x: 265, y: 275 }, { x: 145, y: 315 }, { x: 92, y: 235 }, { x: 125, y: 165 }, 70
  );
  addCubicSamples(
    { x: 125, y: 165 }, { x: 158, y: 85 }, { x: 292, y: 100 }, { x: 345, y: 160 }, 70
  );
  addCubicSamples(
    { x: 345, y: 160 }, { x: 392, y: 212 }, { x: 370, y: 235 }, { x: 330, y: 240 }, 55
  );
  addCubicSamples(
    { x: 330, y: 240 }, { x: 375, y: 198 }, { x: 410, y: 108 }, { x: 430, y: 30 }, 85
  );

  cumLen = [0];
  totalLen = 0;
  for (var j = 1; j < curvePts.length; j++) {
    var dx = curvePts[j].x - curvePts[j - 1].x;
    var dy = curvePts[j].y - curvePts[j - 1].y;
    totalLen += Math.sqrt(dx * dx + dy * dy);
    cumLen.push(totalLen);
  }
}

function pointAtS(s) {
  s = Math.max(0, Math.min(totalLen, s));
  for (var i = 1; i < cumLen.length; i++) {
    if (cumLen[i] >= s) {
      var a = curvePts[i - 1], b = curvePts[i];
      var span = cumLen[i] - cumLen[i - 1] || 1;
      var t = (s - cumLen[i - 1]) / span;
      return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
    }
  }
  return curvePts[curvePts.length - 1];
}

function pointAtFrac(f) {
  return pointAtS(f * totalLen);
}

function segmentPolyline(f0, f1, samples) {
  var pts = [];
  for (var i = 0; i <= samples; i++) {
    var p = pointAtFrac(f0 + (f1 - f0) * i / samples);
    pts.push([p.x, p.y]);
  }
  return pts;
}

function ptsAttr(pts) {
  return pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
}

function makePathFromCurve() {
  return 'M30 570 C125 525 215 430 265 275 ' +
    'C145 315 92 235 125 165 ' +
    'C158 85 292 100 345 160 ' +
    'C392 212 370 235 330 240 ' +
    'C375 198 410 108 430 30';
}

function density(p) {
  return 1.05 + 0.72 * (p.x / W) + 0.48 * ((H - p.y) / H) + 0.18 * Math.sin(p.x / 58);
}

function riemannSum(n, alpha) {
  var ds = totalLen / n / 100;
  var sum = 0;
  for (var i = 0; i < n; i++) {
    sum += density(pointAtS((i + alpha) * totalLen / n)) * ds;
  }
  return sum;
}

function computeFineIntegral() {
  var n = 900, ds = totalLen / n / 100, s = 0;
  for (var i = 0; i < n; i++) s += density(pointAtS((i + 0.5) * totalLen / n)) * ds;
  return s;
}

function labelText(txt, x, y, size, anchor) {
  var t = labelLayer.text(txt)
    .font({ family: 'Georgia, Times New Roman, serif', size: size || 30, style: 'italic', anchor: anchor || 'start' })
    .fill(black);
  t.move(x, y);
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  return t;
}

function smallText(group, txt, x, y, size, anchor) {
  var t = group.text(txt)
    .font({ family: 'Georgia, Times New Roman, serif', size: size || 24, style: 'italic', anchor: anchor || 'start' })
    .fill(black);
  t.move(x, y);
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
