function cubicPoint(p0, p1, p2, p3, t) {
  var u = 1 - t;
  return {
    x: u * u * u * p0.x + 3 * u * u * t * p1.x + 3 * u * t * t * p2.x + t * t * t * p3.x,
    y: u * u * u * p0.y + 3 * u * u * t * p1.y + 3 * u * t * t * p2.y + t * t * t * p3.y
  };
}

function addCubicSamples(p0, p1, p2, p3, count) {
  for (var i = 0; i <= count; i++) {
    if (curvePts.length && i === 0) continue;
    curvePts.push(cubicPoint(p0, p1, p2, p3, i / count));
  }
}

function buildCurve() {
  curvePts = [];
  addCubicSamples(
    { x: 30, y: 570 }, { x: 125, y: 525 }, { x: 215, y: 430 }, { x: 265, y: 275 }, 90
  );
  addCubicSamples(
    { x: 265, y: 275 }, { x: 145, y: 315 }, { x: 92, y: 235 }, { x: 125, y: 165 }, 70
  );
  addCubicSamples(
    { x: 125, y: 165 }, { x: 158, y: 85 }, { x: 292, y: 100 }, { x: 345, y: 160 }, 70
  );
  addCubicSamples(
    { x: 345, y: 160 }, { x: 392, y: 212 }, { x: 370, y: 235 }, { x: 330, y: 240 }, 55
  );
  addCubicSamples(
    { x: 330, y: 240 }, { x: 375, y: 198 }, { x: 410, y: 108 }, { x: 430, y: 30 }, 85
  );

  cumLen = [0];
  totalLen = 0;
  for (var j = 1; j < curvePts.length; j++) {
    var dx = curvePts[j].x - curvePts[j - 1].x;
    var dy = curvePts[j].y - curvePts[j - 1].y;
    totalLen += Math.sqrt(dx * dx + dy * dy);
    cumLen.push(totalLen);
  }
}

function pointAtS(s) {
  s = Math.max(0, Math.min(totalLen, s));
  for (var i = 1; i < cumLen.length; i++) {
    if (cumLen[i] >= s) {
      var a = curvePts[i - 1], b = curvePts[i];
      var span = cumLen[i] - cumLen[i - 1] || 1;
      var t = (s - cumLen[i - 1]) / span;
      return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
    }
  }
  return curvePts[curvePts.length - 1];
}

function pointAtFrac(f) {
  return pointAtS(f * totalLen);
}

function segmentPolyline(f0, f1, samples) {
  var pts = [];
