    .move(610, 598).fill(black);
  r1.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });

  var r2 = formulaLayer.text('approaches  ∫C f ds ≈ ' + integralValue.toFixed(3))
    .font({ family: 'Georgia, Times New Roman, serif', size: 20, style: 'italic' })
    .move(610, 626).fill(black);
  r2.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });

  formulaLayer.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Local mass ≈ density at a sample point times arc length.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Local mass approximation', 'For one short arc, the density is treated as nearly constant. The term f(P*ₖ)Δsₖ is one piece of the Riemann sum whose limit is the scalar line integral.');
    });
}

function insetPoint(t) {
  return cubicPoint({ x: 592, y: 545 }, { x: 650, y: 552 }, { x: 720, y: 540 }, { x: 795, y: 500 }, t);
}

function drawInset() {
  insetLayer.clear();

  var ipts = [];
  for (var i = 0; i <= 80; i++) {
    var p = insetPoint(i / 80);
    ipts.push([p.x, p.y]);
  }

  insetLayer.polyline(ptsAttr(ipts)).fill('none').stroke({
    color: blue, width: 7, linecap: 'round', linejoin: 'round'
  });

  var a = insetPoint(0), b = insetPoint(1), sp = insetPoint(sampleAlpha);
  insetLayer.circle(20).center(a.x, a.y).fill(blue);
  insetLayer.circle(20).center(b.x, b.y).fill(blue);

  smallText(insetLayer, 'Pₖ₋₁', 562, 570, 31);
  smallText(insetLayer, 'Pₖ', 807, 494, 31);

  drawDimensionLine(insetLayer, 600, 491, 777, 449, 'Δsₖ', 690, 467);

  var redPt = insetLayer.circle(22).center(sp.x, sp.y).fill(red);
  redPt.css('cursor', 'grab')
    .on('mousemove', function (e) { showTooltip('Drag P*ₖ: choose where the density is sampled inside this subarc.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Sample point P*ₖ', 'The sample point may be chosen anywhere in the kth subarc. As the partition is refined, all choices give nearly the same limiting total.');
    });

  smallText(insetLayer, 'P*ₖ(x*ₖ, y*ₖ, z*ₖ)', sp.x - 12, sp.y + 30, 28);

  var dragging = false;
  redPt.on('pointerdown', function (e) {
    dragging = true;
    redPt.css('cursor', 'grabbing');
    if (redPt.node.setPointerCapture) redPt.node.setPointerCapture(e.pointerId);
    e.preventDefault();
  });

  draw.on('pointermove', function (e) {
    if (!dragging) return;
    var pt = draw.node.createSVGPoint();
    pt.x = e.clientX;
    pt.y = e.clientY;
    var loc = pt.matrixTransform(draw.node.getScreenCTM().inverse());

    var bestT = sampleAlpha, bestD = Infinity;
    for (var j = 0; j <= 140; j++) {
      var t = j / 140, q = insetPoint(t);
      var d = (q.x - loc.x) * (q.x - loc.x) + (q.y - loc.y) * (q.y - loc.y);
      if (d < bestD) {
        bestD = d;
        bestT = t;
      }
    }
    sampleAlpha = bestT;
    redraw();
  });

  draw.on('pointerup pointerleave', function () {
    dragging = false;
    redPt.css('cursor', 'grab');
  });
}

function redraw() {
  dynamicLayer.clear();
  labelLayer.clear();

  var sum = riemannSum(nSegments, sampleAlpha);
  var selectedK = Math.min(nSegments - 1, Math.max(2, Math.round(0.58 * nSegments)));
  var f0 = (selectedK - 1) / nSegments;
  var f1 = selectedK / nSegments;

  dynamicLayer.polyline(ptsAttr(segmentPolyline(f0, f1, 30)))
    .fill('none')
    .stroke({ color: '#ffe18f', width: 13, linecap: 'round', linejoin: 'round', opacity: 0.9 });

  var hi = dynamicLayer.polyline(ptsAttr(segmentPolyline(f0, f1, 30)))
    .fill('none')
    .stroke({ color: blue, width: 7, linecap: 'round', linejoin: 'round' });
  hi.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('The highlighted kth subarc has length Δsₖ.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The kth subarc', 'This is one representative partition piece. Its contribution to the scalar line integral is approximated by f(P*ₖ)Δsₖ.');
    });

  for (var j = 0; j <= nSegments; j++) {
    var p = pointAtFrac(j / nSegments);
    var r = nSegments > 24 ? 5 : 8;
    dynamicLayer.circle(2 * r).center(p.x, p.y).fill(blue);
  }

  if (nSegments >= 12) {
    for (var i = 0; i < nSegments; i++) {
      var rp = pointAtFrac((i + sampleAlpha) / nSegments);
      dynamicLayer.circle(nSegments > 26 ? 5 : 7).center(rp.x, rp.y).fill(red).opacity(nSegments > 26 ? 0.45 : 0.62);
    }
  }

  var pk0 = pointAtFrac(f0), pk1 = pointAtFrac(f1);
  var offY = pk0.y < 225 ? 44 : -48;
  drawDimensionLine(dynamicLayer, pk0.x - 5, pk0.y + offY, pk1.x + 5, pk1.y + offY, 'Δsₖ',
    (pk0.x + pk1.x) / 2, (pk0.y + pk1.y) / 2 + offY - 38);

  dynamicLayer.line(235, 365, pk0.x, pk0.y + 8)
    .stroke({ color: black, width: 2 })
    .marker('end', arrowMarker);
  labelText('Mass ΔMₖ', 68, 342, 33);

  labelText('P = P₀', 16, 596, 33);
  for (var m = 1; m <= 3 && m < nSegments; m++) {
    if (m === selectedK - 1) continue;
    var pm = pointAtFrac(m / nSegments);
    labelText('P' + ['₀', '₁', '₂', '₃'][m], pm.x + 14, pm.y + 12, 29);
  }

  labelText('Pₖ₋₁', pk0.x - 62, pk0.y + 28, 31);
  labelText('Pₖ', pk1.x + 34, pk1.y - 2, 31);

  var pn1 = pointAtFrac((nSegments - 1) / nSegments);
  labelText('Pₙ₋₁', pn1.x + 15, pn1.y - 5, 31);
  var q = pointAtFrac(1);
  labelText('Q = Pₙ', q.x - 15, q.y - 48, 31);

  drawInset();
  drawFormulaAndReadout(sum);
}

function update_numberOfSegments(v) {
  nSegments = Math.max(4, Math.min(40, Math.round(v)));
  var out = document.getElementById('numberOfSegmentsVal');
  var inp = document.getElementById('numberOfSegmentsInput');
  if (out) out.value = String(nSegments);
  if (inp) inp.value = String(nSegments);
  redraw();
}

var demoSteps = [
  {
    title: 'Coarse partition',
    narration: 'The curve is divided into a small number of arcs. The highlighted kth arc has length Δsₖ, and its mass is approximated by evaluating the density at one chosen sample point on that arc.',
    state: { numberOfSegments: 8 }
  },
  {
    title: 'Move the sample point',
    narration: 'Drag the red point P*ₖ within the zoomed kth arc. The local term f(P*ₖ)Δsₖ changes because the density is sampled at a different point, but it is still an approximation to the same small piece of mass.',
    state: { numberOfSegments: 8 }
  },
  {
    title: 'Refine the curve partition',
    narration: 'Increase n so the curve is split into many shorter arcs. The sample points multiply along the curve, Δsₖ becomes small, and the displayed Riemann sum stabilizes toward ∫C f ds.',
    state: { numberOfSegments: 28 }
  }
];

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];
  var narr = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (narr) narr.textContent = step.narration;
  if (lab) lab.textContent = (currentStep + 1) + '/' + demoSteps.length + ' ' + step.title;
  if (step.state && step.state.numberOfSegments != null) {
    update_numberOfSegments(step.state.numberOfSegments);
  }
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

buildCurve();
integralValue = computeFineIntegral();
drawZoomArrow();
drawBaseCurve();
applyStep(0);

window.update_numberOfSegments = update_numberOfSegments;
window.prevStep = prevStep;
window.nextStep = nextStep;

window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A scalar line integral is built by partitioning a curve into short arc-length pieces, approximating each piece’s mass by f at one sample point times Δs, and taking the limit as the partition is refined.
KEY INSIGHT (what students should walk away understanding): A line integral is the limiting total of many local approximations: density at a sample point times the tiny arc length containing it.
DEMO STEPS: 3 guided steps — implement the step player in #ui

FULL BLUEPRINT:
