// @FIGURE_CODE_BEGIN
var W = 900, H = 820;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var blue = '#2aa4dc';
var red = '#ef5454';
var black = '#222222';
var gray = '#bfc1c4';
var pale = '#fff1d3';
var nSegments = 8;
var sampleAlpha = 0.50;
var currentStep = 0;

var curvePts = [];
var cumLen = [];
var totalLen = 0;
var integralValue = 0;
var draggingSample = false;

var zoomArrowLayer = draw.group();
var curveLayer = draw.group();
var sampleLayer = draw.group();
var dynamicLayer = draw.group();
var insetLayer = draw.group();
var formulaLayer = draw.group();
var labelLayer = draw.group();

var arrowMarker = draw.marker(11, 11, function (add) {
  add.path('M0,0 L11,5.5 L0,11 z').fill(black);
});
arrowMarker.ref(10, 5.5).orient('auto');

var arrowStartMarker = draw.marker(11, 11, function (add) {
  add.path('M11,0 L0,5.5 L11,11 z').fill(black);
});
arrowStartMarker.ref(1, 5.5).orient('auto');

function cubicPoint(p0, p1, p2, p3, t) {
  var u = 1 - t;
  return {
    x: u * u * u * p0.x + 3 * u * u * t * p1.x + 3 * u * t * t * p2.x + t * t * t * p3.x,
    y: u * u * u * p0.y + 3 * u * u * t * p1.y + 3 * u * t * t * p2.y + t * t * t * p3.y
  };
}

function addCubicSamples(p0, p1, p2, p3, count) {
  for (var i = 0; i <= count; i++) {
    if (curvePts.length && i === 0) continue;
    curvePts.push(cubicPoint(p0, p1, p2, p3, i / count));
  }
}

function mainPathString() {
  return 'M30 650 ' +
    'C130 595 210 510 280 405 ' +
    'C305 365 278 335 240 322 ' +
    'C125 330 82 245 112 185 ' +
    'C145 95 285 105 345 178 ' +
    'C392 228 380 277 336 302 ' +
    'C386 248 420 150 430 60';
}

function buildCurve() {
  curvePts = [];
  addCubicSamples({ x: 30, y: 650 }, { x: 130, y: 595 }, { x: 210, y: 510 }, { x: 280, y: 405 }, 90);
  addCubicSamples({ x: 280, y: 405 }, { x: 305, y: 365 }, { x: 278, y: 335 }, { x: 240, y: 322 }, 45);
  addCubicSamples({ x: 240, y: 322 }, { x: 125, y: 330 }, { x: 82, y: 245 }, { x: 112, y: 185 }, 70);
  addCubicSamples({ x: 112, y: 185 }, { x: 145, y: 95 }, { x: 285, y: 105 }, { x: 345, y: 178 }, 80);
  addCubicSamples({ x: 345, y: 178 }, { x: 392, y: 228 }, { x: 380, y: 277 }, { x: 336, y: 302 }, 60);
  addCubicSamples({ x: 336, y: 302 }, { x: 386, y: 248 }, { x: 420, y: 150 }, { x: 430, y: 60 }, 85);

  cumLen = [0];
  totalLen = 0;
  for (var j = 1; j < curvePts.length; j++) {
    var dx = curvePts[j].x - curvePts[j - 1].x;
    var dy = curvePts[j].y - curvePts[j - 1].y;
    totalLen += Math.sqrt(dx * dx + dy * dy);
    cumLen.push(totalLen);
  }
}

function pointAtS(s) {
  s = Math.max(0, Math.min(totalLen, s));
  for (var i = 1; i < cumLen.length; i++) {
    if (cumLen[i] >= s) {
      var a = curvePts[i - 1], b = curvePts[i];
      var span = cumLen[i] - cumLen[i - 1] || 1;
      var t = (s - cumLen[i - 1]) / span;
      return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
    }
  }
  return curvePts[curvePts.length - 1];
}

function pointAtFrac(f) {
  return pointAtS(f * totalLen);
}

function ptsAttr(pts) {
  return pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
}

function fixedKSubarcPoints(samples) {
  var pts = [];
  var controls = [
    [{ x: 240, y: 322 }, { x: 125, y: 330 }, { x: 82, y: 245 }, { x: 112, y: 185 }],
    [{ x: 112, y: 185 }, { x: 145, y: 95 }, { x: 285, y: 105 }, { x: 345, y: 178 }],
    [{ x: 345, y: 178 }, { x: 392, y: 228 }, { x: 380, y: 277 }, { x: 336, y: 302 }]
  ];
  var per = Math.max(10, Math.floor(samples / controls.length));
  for (var c = 0; c < controls.length; c++) {
    for (var i = 0; i <= per; i++) {
      if (pts.length && i === 0) continue;
      var p = cubicPoint(controls[c][0], controls[c][1], controls[c][2], controls[c][3], i / per);
      pts.push([p.x, p.y]);
    }
  }
  return pts;
}

function density(p) {
  return 1.05 + 0.72 * (p.x / W) + 0.48 * ((H - p.y) / H) + 0.18 * Math.sin(p.x / 58);
}

function riemannSum(n, alpha) {
  var ds = totalLen / n / 100;
  var sum = 0;
  for (var i = 0; i < n; i++) {
    sum += density(pointAtS((i + alpha) * totalLen / n)) * ds;
  }
  return sum;
}

function computeFineIntegral() {
  var n = 1200, ds = totalLen / n / 100, s = 0;
  for (var i = 0; i < n; i++) s += density(pointAtS((i + 0.5) * totalLen / n)) * ds;
  return s;
}

function haloText(group, txt, x, y, size, anchor) {
