    .font({ family: 'Georgia, Times New Roman, serif', size: size || 30, style: 'italic', anchor: anchor || 'start' })
    .fill(black);
  t.move(x, y);
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  return t;
}

function centeredMath(group, txt, cx, cy, size) {
  var t = group.text(txt)
    .font({ family: 'Georgia, Times New Roman, serif', size: size || 28, style: 'italic', anchor: 'middle' })
    .fill(black);
  t.center(cx, cy);
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  return t;
}

function drawDimensionLine(group, x1, y1, x2, y2, label, lx, ly, size) {
  group.line(x1, y1, x2, y2)
    .stroke({ color: black, width: 2.2, linecap: 'round' })
    .marker('start', arrowStartMarker).marker('end', arrowMarker);

  var vx = x2 - x1, vy = y2 - y1;
  var len = Math.sqrt(vx * vx + vy * vy) || 1;
  var nx = -vy / len, ny = vx / len;
  group.line(x1 - nx * 22, y1 - ny * 22, x1 + nx * 22, y1 + ny * 22).stroke({ color: black, width: 2.2 });
  group.line(x2 - nx * 22, y2 - ny * 22, x2 + nx * 22, y2 + ny * 22).stroke({ color: black, width: 2.2 });
  centeredMath(group, label, lx, ly, size || 30);
}

function drawZoomArrow() {
