      var a = curvePts[i - 1], b = curvePts[i];
      var span = cumLen[i] - cumLen[i - 1] || 1;
      var t = (s - cumLen[i - 1]) / span;
      return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
    }
  }
  return curvePts[curvePts.length - 1];
}

