      showPopup('Zoomed kth subarc', 'The inset isolates one short piece of the curve. The mass of this piece is approximated by density at the red sample point times its arc length Δsₖ.');
    });

  var a = insetPoint(0), b = insetPoint(1), sp = insetPoint(sampleAlpha);

  insetLayer.circle(21).center(a.x, a.y).fill(blue);
  insetLayer.circle(21).center(b.x, b.y).fill(blue);

  haloText(insetLayer, 'Pₖ₋₁', 544, 664, 34);
  haloText(insetLayer, 'Pₖ', 846, 568, 34);

  drawDimensionLine(insetLayer, 584, 610, 814, 562, 'Δsₖ', 700, 586, 35);

  var redPt = insetLayer.circle(23).center(sp.x, sp.y).fill(red);
  redPt.css('cursor', 'grab')
    .on('mousemove', function (e) { showTooltip('Drag P*ₖ along the arc to choose the density sample point.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Sample point P*ₖ', 'The sample point can be chosen anywhere within the kth subarc. For a coarse partition the estimate can change noticeably; as Δsₖ shrinks, the choice matters less.');
    })
    .on('pointerdown', function (e) {
      draggingSample = true;
      redPt.css('cursor', 'grabbing');
      if (redPt.node.setPointerCapture) redPt.node.setPointerCapture(e.pointerId);
      e.preventDefault();
    });

  haloText(insetLayer, 'P*ₖ(x*ₖ, y*ₖ, z*ₖ)', sp.x - 16, sp.y + 31, 31);
}

function drawFormulaAndReadout(sum) {
  formulaLayer.clear();

  formulaLayer.rect(470, 78).move(122, 720)
    .fill('#ffffff')
    .stroke({ color: gray, width: 4 });

  formulaLayer.text('ΔMₖ ≈ f(x*ₖ, y*ₖ, z*ₖ) Δsₖ')
    .font({ family: 'Georgia, Times New Roman, serif', size: 35, style: 'italic', anchor: 'middle' })
    .center(357, 759)
    .fill(black);

  var r = formulaLayer.text('Σ f(P*ᵢ) Δsᵢ ≈ ' + sum.toFixed(3) + '    →    ∫C f ds ≈ ' + integralValue.toFixed(3))
    .font({ family: 'Georgia, Times New Roman, serif', size: 17, style: 'italic' })
    .move(610, 730)
    .fill('#555555')
    .opacity(0.58);
  r.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4, 'stroke-linejoin': 'round' });

  formulaLayer.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('One local mass term: density at P*ₖ times arc length Δsₖ.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Local mass approximation', 'On a very short arc the density is treated as nearly constant. The terms f(P*ᵢ)Δsᵢ are added and then a limit is taken as the partition is refined.');
    });
}

function drawMainLabels() {
  labelLayer.clear();

  haloText(labelLayer, 'P = P₀', 14, 665, 36);
  haloText(labelLayer, 'P₁', 156, 579, 34);
  haloText(labelLayer, 'P₂', 252, 500, 34);
  haloText(labelLayer, 'P₃', 324, 398, 34);

  haloText(labelLayer, 'Pₖ₋₁', 160, 343, 38);
  haloText(labelLayer, 'Pₖ', 374, 294, 36);

  haloText(labelLayer, 'Pₙ₋₁', 434, 142, 34);
  haloText(labelLayer, 'Q = Pₙ', 418, 12, 36);

  haloText(labelLayer, 'Mass ΔMₖ', 78, 430, 38);
  labelLayer.line(236, 413, 241, 323)
    .stroke({ color: black, width: 2.4 })
    .marker('end', arrowMarker);
}

function redraw() {
  dynamicLayer.clear();
  sampleLayer.clear();

  var sum = riemannSum(nSegments, sampleAlpha);

  var kpts = fixedKSubarcPoints(130);
  dynamicLayer.polyline(ptsAttr(kpts))
    .fill('none')
    .stroke({ color: '#ffe18f', width: 12, linecap: 'round', linejoin: 'round', opacity: 0.88 });
  var hi = dynamicLayer.polyline(ptsAttr(kpts))
    .fill('none')
    .stroke({ color: blue, width: 6.5, linecap: 'round', linejoin: 'round' });
  hi.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('The kth subarc has arc length Δsₖ.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The kth subarc', 'This highlighted piece represents one term in the Riemann sum. Its local mass is approximated by f(P*ₖ)Δsₖ.');
    });

  drawDimensionLine(dynamicLayer, 180, 284, 264, 250, 'Δsₖ', 222, 230, 34);

  for (var j = 0; j <= nSegments; j++) {
    var p = pointAtFrac(j / nSegments);
    var r = nSegments > 26 ? 5 : 8;
    dynamicLayer.circle(2 * r).center(p.x, p.y).fill(blue);
  }

  dynamicLayer.circle(18).center(240, 322).fill(blue);
  dynamicLayer.circle(18).center(336, 302).fill(blue);

  var showAllSamples = nSegments >= 12;
  if (showAllSamples) {
    for (var i = 0; i < nSegments; i++) {
      var rp = pointAtFrac((i + sampleAlpha) / nSegments);
      sampleLayer.circle(nSegments > 26 ? 6 : 8)
        .center(rp.x, rp.y)
        .fill(red)
        .opacity(nSegments > 26 ? 0.46 : 0.62);
    }
  }

  drawInset();
  drawFormulaAndReadout(sum);
  drawMainLabels();
}

draw.on('pointermove', function (e) {
  if (!draggingSample) return;

  var pt = draw.node.createSVGPoint();
  pt.x = e.clientX;
  pt.y = e.clientY;
  var loc = pt.matrixTransform(draw.node.getScreenCTM().inverse());

  var bestT = sampleAlpha, bestD = Infinity;
  for (var j = 0; j <= 180; j++) {
    var t = j / 180;
    var q = insetPoint(t);
    var d = (q.x - loc.x) * (q.x - loc.x) + (q.y - loc.y) * (q.y - loc.y);
    if (d < bestD) {
      bestD = d;
      bestT = t;
    }
  }
  sampleAlpha = bestT;
  redraw();
});

draw.on('pointerup', function () { draggingSample = false; });
draw.on('pointerleave', function () { draggingSample = false; });

function update_numberOfSegments(v) {
  nSegments = Math.max(4, Math.min(40, Math.round(v)));
  var out = document.getElementById('numberOfSegmentsVal');
  var inp = document.getElementById('numberOfSegmentsInput');
  if (out) out.value = String(nSegments);
  if (inp) inp.value = String(nSegments);
  redraw();
}

var demoSteps = [
  {
    title: 'Coarse partition',
    narration: 'The curve is divided into a small number of arcs. The highlighted kth arc has length Δsₖ, and its mass is approximated by evaluating the density at one chosen sample point on that arc.',
    state: { numberOfSegments: 8 }
  },
  {
    title: 'Move the sample point',
    narration: 'Drag the red point P*ₖ within the zoomed kth arc. The local term f(P*ₖ)Δsₖ changes because the density is sampled at a different point, but it is still an approximation to the same small piece of mass.',
    state: { numberOfSegments: 8 }
  },
  {
    title: 'Refine the curve partition',
    narration: 'Increase n so the curve is split into many shorter arcs. The sample points multiply along the curve, Δsₖ becomes small, and the displayed Riemann sum stabilizes toward ∫C f ds.',
    state: { numberOfSegments: 28 }
  }
];

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];
  var narr = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (narr) narr.textContent = step.narration;
  if (lab) lab.textContent = (currentStep + 1) + '/' + demoSteps.length + ' ' + step.title;
  if (step.state && step.state.numberOfSegments != null) update_numberOfSegments(step.state.numberOfSegments);
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

buildCurve();
integralValue = computeFineIntegral();
drawZoomArrow();
drawBaseCurve();
applyStep(0);

window.update_numberOfSegments = update_numberOfSegments;
window.prevStep = prevStep;
window.nextStep = nextStep;

window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A scalar line integral is built by partitioning a curve into short arc-length pieces, approximating each piece’s mass by f at one sample point times Δs, and taking the limit as the partition is refined.
KEY INSIGHT (what students should walk away understanding): A line integral is the limiting total of many local approximations: density at a sample point times the tiny arc length containing it.
DEMO STEPS: 3 guided steps — implement the step player in #ui

FULL BLUEPRINT:
