    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Curve C', 'A scalar line integral adds contributions along a curve. Each small contribution uses an arc length Δs rather than a horizontal width Δx.');
    });
}

function insetPoint(t) {
  return cubicPoint({ x: 575, y: 650 }, { x: 660, y: 660 }, { x: 765, y: 620 }, { x: 835, y: 580 }, t);
}

function drawInset() {
  insetLayer.clear();

  var ipts = [];
  for (var i = 0; i <= 95; i++) {
