function drawFormula(sum) {
  formulaLayer.clear();

  formulaLayer.rect(600, 88).move(110, 718)
    .fill('#ffffff')
    .stroke({ color: gray, width: 4 });

  formulaLayer.text('ΔMₖ ≈ f(x*ₖ, y*ₖ, z*ₖ) Δsₖ')
    .font({ family: 'Georgia, Times New Roman, serif', size: 38, style: 'italic', anchor: 'middle' })
    .center(410, 762)
